  my $w=$1; my $s=$-[1]; my $l=length($w);
  my $lc=lc $w;
  if (exists $mp{$lc}) {
    # if multiple fams, union options
    my %seen; my @opts;
    for my $fi (@{$mp{$lc}}) { for my $o (@{$fams[$fi]}){ my $lco=lc $o; next if $seen{$lco}++; push @opts,$o; } }
