    if ($origw =~ /^[A-Z]+$/) { $rep=uc $opt_raw; }
    elsif ($origw =~ /^[A-Z]/) { $rep=lc $opt_raw; $rep=ucfirst $rep; }
    else { $rep=lc $opt_raw; }
    # if rep case-insensitively equals orig, skip (no change needed but still same)
    substr($out,$t->{start},$t->{len},$rep);
  }
