# show log lines
while ($log=~/Overfull \\hbox(.*?)too wide\) in paragraph at lines (.*?)\n(.*)/g){ print "OVER $1 too wide lines $2 :: $3\n"; }
# restore orig for next steps? keep short tex in input.tex for now
# save
